public protocol OffshelfEngineProtocol: AnyObject, Sendable {
    
    func changePassphrase(newPassphrase: String) throws 
    
    func devices() throws  -> [Device]
    
    func events()  -> [ActivityEvent]
    
    func hosts()  -> [HostRule]
    
    /**
     * A folder's contents, folders first, then by name.
     */
    func list(path: String) throws  -> [Entry]
    
    /**
     * The master key, for the Keychain, so later launches skip the passphrase.
     */
    func masterKey()  -> Data
    
    /**
     * Drops this Mac's copy. Returns the bytes freed.
     */
    func offload(path: String) throws  -> UInt64
    
    /**
     * Offloads everything that isn't pinned.
     */
    func offloadAll()  -> UInt64
    
    /**
     * Bytes of unpinned files on this Mac (what "Offload everything" frees).
     */
    func offloadableBytes()  -> UInt64
    
    func pin(path: String) throws 
    
    /**
     * Re-picks the host and re-verifies the tree (after wake, or "Try again").
     */
    func reconnect() 
    
    /**
     * Names matching `query` anywhere on the shelf (names only).
     */
    func search(query: String, limit: UInt32)  -> [String]
    
    func setHosts(hosts: [HostRule]) 
    
    /**
     * The Wi-Fi network the Mac is on, or `None` off Wi-Fi.
     */
    func setNetwork(ssid: String?) 
    
    func setSettings(settings: EngineSettings) 
    
    func settings()  -> EngineSettings
    
    /**
     * Starts sync, uploads and the NFS server, and mounts at `mountpoint`.
     */
    func start(mountpoint: String) throws 
    
    func status()  -> Status
    
    func unmount() throws 
    
    func unpin(path: String) throws 
    
    /**
     * Copies a local file or folder onto the shelf under `to` (a shelf
     * folder). Runs in the background; progress shows in the activity list.
     */
    func uploadLocal(localPath: String, to: String) 
    
    func usage() throws  -> ShelfUsage
    
}
