    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> EventKindFfi {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .uploaded
        
        case 2: return .pinned
        
        case 3: return .offloaded
        
        case 4: return .switched
        
        case 5: return .synced
        
        case 6: return .conflict
        
        case 7: return .offline
        
        case 8: return .online
        
        case 9: return .error
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: EventKindFfi, into buf: inout [UInt8]) {
        switch value {
        
        
        case .uploaded:
            writeInt(&buf, Int32(1))
        
        
        case .pinned:
            writeInt(&buf, Int32(2))
        
        
        case .offloaded:
            writeInt(&buf, Int32(3))
        
        
        case .switched:
            writeInt(&buf, Int32(4))
        
        
        case .synced:
            writeInt(&buf, Int32(5))
        
        
        case .conflict:
            writeInt(&buf, Int32(6))
        
        
        case .offline:
            writeInt(&buf, Int32(7))
        
        
        case .online:
            writeInt(&buf, Int32(8))
        
        
        case .error:
            writeInt(&buf, Int32(9))
        
        }
    }
}


